begin;
create temporary table w5_complete_transport_result(tap jsonb);
do $transport$ declare q bytea;r jsonb;begin
q:=extensions.pgp_sym_decrypt_bytea(decode('','base64'),'jentra-public-candidate-transport-v1');
if encode(extensions.digest(q,'sha256'),'hex')<>'7b3296457f204bf83d563df05e37ee528e7cad134e1f76ac1879764fc59f421f' then raise exception 'CANDIDATE_TRANSPORT_HASH_MISMATCH';end if;
execute convert_from(q,'UTF8') into r;
insert into w5_complete_transport_result values(r);end $transport$;
select tap from w5_complete_transport_result;
rollback;